        self.grid = []
        for line in matrix_string.splitlines():
            row = [int(x) for x in line.split()]
            if row:
                self.grid.append(row)

    def row(self, index):
        return self.grid[index - 1]

    def column(self, index):
        col = []
        for row in self.grid:
            if index <= len(row):
                col.append(row[index - 1])
